import threading

def reproduce(connect, service) -> str | None:
    key = "repro-idempotency-key"
    account_id = 1
    # discover a safe amount that won't violate CHECK(balance>=0)
    try:
        with connect() as c:
            row = c.execute("SELECT balance FROM accounts WHERE id = %s", (account_id,)).fetchone()
            init_bal = row[0] if row else 1000000
    except Exception:
        init_bal = 1000000
    if init_bal is None:
        init_bal = 1000000
    # use amount 1 if we can afford N charges, else 0 (still detects duplicate rows)
    N = 20
    amount = 1 if init_bal >= N else 0

    barrier = threading.Barrier(N)
    results = []
    errors = []

    def worker():
        try:
            with connect() as conn:
                barrier.wait()
                try:
                    r = service.pay(conn, key, account_id, amount)
                    results.append(r)
                except Exception as e:
                    errors.append(repr(e))
        except Exception as e:
            errors.append(repr(e))

    threads = [threading.Thread(target=worker) for _ in range(N)]
    for t in threads:
        t.start()
    for t in threads:
        t.join()

    # ground truth from DB
    try:
        with connect() as conn:
            cnt = conn.execute(
                "SELECT COUNT(*) FROM payments WHERE idempotency_key = %s", (key,)
            ).fetchone()[0]
            bal = conn.execute(
                "SELECT balance FROM accounts WHERE id = %s", (account_id,)
            ).fetchone()[0]
    except Exception as e:
        return f"could not verify DB state: {e!r} results={results} errors={errors}"

    true_count = sum(1 for x in results if x is True)
    false_count = sum(1 for x in results if x is False)

    if cnt != 1:
        return (
            f"idempotency violated: payment {key!r} charged {cnt} times (expected 1); "
            f"True returns={true_count}/{N}, errors={len(errors)}, balance={bal} init={init_bal}"
        )
    if true_count != 1 or false_count != N - 1:
        return (
            f"idempotency return-value violated: expected exactly 1 True and {N-1} False, "
            f"got {true_count} True / {false_count} False (rows={cnt}) errors={errors}"
        )
    # also check balance movement matches exactly one charge
    expected_bal = init_bal - amount
    if bal != expected_bal:
        return (
            f"balance violated: expected {expected_bal} after single charge of {amount}, got {bal} "
            f"(init={init_bal}, rows={cnt})"
        )
    return None
